// src/components/Img.jsx — lazy image that prefers the optimized "-sm.webp" sibling
// generated by `npm run images`, and falls back to the original file if it is missing.
import { mediaUrl } from '../data/tracks'

const SITE = /^https?:\/\/(www\.)?rickypassword\.com/i

// eslint-disable-next-line react-refresh/only-export-components
export function thumbUrl(src = '') {
  const local = src.replace(SITE, '')
  if (/^https?:\/\//i.test(local) || !/\.(jpe?g|png)$/i.test(local)) return mediaUrl(src)
  return mediaUrl(local.replace(/\.(jpe?g|png)$/i, '-sm.webp'))
}

export default function Img({ src = '', alt = '', full = false, ...rest }) {
  // same-site absolute URLs (used in news data) load from the current origin
  const original = mediaUrl(src.replace(SITE, ''))
  return (
    <img
      src={full ? original : thumbUrl(src)}
      alt={alt}
      loading="lazy"
      decoding="async"
      onError={(e) => {
        const img = e.currentTarget
        if (img.src !== new URL(original, window.location.href).href) img.src = original
        else img.style.visibility = 'hidden' // missing file: let the placeholder background show
      }}
      {...rest}
    />
  )
}
